-- inventory.zip_centroids — US ZIP code centroid lookup, used to plot the
-- Droptop customer heatmap (Customers module) by ZIP without needing any
-- geocoding API key, per-lookup cost, or rate limit. Resolution is
-- zip-centroid, not rooftop-exact — the right fit for a "where are
-- customers coming from" density view rather than pin-exact mapping.
--
-- Data: ~42,000 US ZIP codes with city/state/county/lat/lng, sourced from
-- the midwire/free_zipcode_data community dataset on GitHub (MIT-licensed,
-- pulled 2026-08-31: https://github.com/midwire/free_zipcode_data). A
-- handful of PO-box-only/military/unpopulated ZIPs with no coordinates in
-- that source are simply absent here — droptop_customers rows with those
-- ZIPs fall out of the heatmap (excluded, not silently mis-plotted) until
-- a real ZIP shows up here.
--
-- Split into 9 numbered part files (this is part 1 of 9) purely because
-- Supabase's dashboard SQL Editor rejects a single query/paste over a
-- couple MB ("Query is too large to be run via the SQL Editor") — the
-- original single-file version of this migration hit that wall at ~2.7MB.
-- Run all 9 parts, in any order — every part repeats the same idempotent
-- DDL (CREATE TABLE IF NOT EXISTS / DROP POLICY IF EXISTS) so none of them
-- depend on another having run first, and every INSERT uses
-- ON CONFLICT (zip) DO NOTHING so re-running any part is harmless. If you
-- have a direct Postgres connection (psql, or Power BI's own connector
-- isn't relevant here since this is a write) available instead of the
-- dashboard editor, all 9 parts can just be concatenated and run as one
-- statement — the split only exists to work around the editor's size cap.
CREATE TABLE IF NOT EXISTS inventory.zip_centroids (
  zip    text PRIMARY KEY,
  city   text,
  state  text,
  county text,
  lat    numeric NOT NULL,
  lng    numeric NOT NULL
);
ALTER TABLE inventory.zip_centroids ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "zip_centroids_select" ON inventory.zip_centroids;
CREATE POLICY "zip_centroids_select" ON inventory.zip_centroids FOR SELECT
  USING (auth.role() = 'authenticated');

